/**
 * docs/effect-ir-kinds.md is generated by scripts/build-kind-reference.mjs
 * from src/effects/ir.ts, src/effects/primitiveNames.ts, and the pinned
 * card JSON. This test fails when the committed file no longer matches
 * what the script builds, so the reference can't drift from the engine.
 */
import { readFileSync } from "node:fs";
import { beforeAll, describe, expect, it } from "vitest";
import { assertCardsPinnedTag, cardsDataPresent } from "../src/index.js";
// @ts-expect-error -- plain .mjs build script without type declarations
import * as reference from "../scripts/build-kind-reference.mjs";

const { buildKindReference, KIND_REFERENCE_COMMAND, KIND_REFERENCE_PATH } =
  reference as {
    buildKindReference: () => string;
    KIND_REFERENCE_COMMAND: string;
    KIND_REFERENCE_PATH: string;
  };

beforeAll(() => {
  if (!cardsDataPresent()) throw new Error("Run npm run fetch-cards");
  assertCardsPinnedTag("v1.147.22");
});

describe("Effect IR kind reference", () => {
  it(`${KIND_REFERENCE_PATH} matches the generator`, () => {
    const committed = readFileSync(
      new URL(`../${KIND_REFERENCE_PATH}`, import.meta.url),
      "utf8",
    );
    const fresh = buildKindReference();
    expect(
      committed === fresh,
      `${KIND_REFERENCE_PATH} is stale. Regenerate it with \`${KIND_REFERENCE_COMMAND}\` and commit the result.`,
    ).toBe(true);
  });

  it("is deterministic", () => {
    expect(buildKindReference()).toBe(buildKindReference());
  });
});
